/**
 * Fotos reales de avatar generadas por los motores de los navegadores (#31, informe veterinario): lo que AvatarCropper sube con canvas.toBlob.
 * - WebP de Chromium 1254 (Playwright): canvas.toBlob('image/webp') de 64x64 = RIFF > VP8X (10) + ICCP (456) + VP8 (872).
 * - JPEG de WebKit 2388 (Playwright, motor de Safari): canvas.toBlob('image/jpeg', 0.85) de 64x64 = JFIF + Exif minimo.
 * Se regeneran con un lienzo de 64 px en cada motor; sin datos personales (degradado y rectangulos).
 */
const decode = (b64: string): Uint8Array => new Uint8Array(Buffer.from(b64, 'base64'));

